-- Add only independently reviewed SIRA service identities and scoped facts; preserve every existing binding.
begin;
do $review$
declare cp uuid;j uuid;a uuid;sid uuid;item jsonb;rules jsonb;step jsonb;docs jsonb;reviewed timestamptz:=now();
begin
 select id into strict j from public.hb_jurisdictions where code='AE-DU';
 select p.id into strict cp from public.hb_country_packs p join public.hb_jurisdictions c on c.id=p.country_jurisdiction_id where c.code='AE' and p.status='active' order by case p.pack_key when 'country:AE' then 0 when 'uae' then 1 else 2 end,p.version desc limit 1;
 insert into public.hb_authorities(country_pack_id,jurisdiction_id,authority_key,name_ar,name_en,scope,official_base_url,portal_url,active,metadata) values(cp,j,'sira-dubai','مؤسسة تنظيم الصناعة الأمنية','Security Industry Regulatory Agency (SIRA)','local','https://www.sira.gov.ae','https://portal.sira.gov.ae',true,'{"review_scope":"Dubai SIRA only"}'::jsonb) on conflict(country_pack_id,authority_key) do nothing;
 select id into strict a from public.hb_authorities where country_pack_id=cp and authority_key='sira-dubai' and active;
 for item in select value from jsonb_array_elements($facts$[{"id":"sira:new-security-activity-license","slug":"sira-new-security-activity-license-dubai","nameAr":"إصدار ترخيص نشاط أمني جديد في دبي","nameEn":"New Security Activity License","category":"government-approvals","type":"ترخيص نشاط أمني جديد","description":"ترخيص النشاط الأمني لدى SIRA لاستكمال إصدار الرخصة التجارية لدى جهة الترخيص في دبي؛ ليس اعتماد نظام كاميرات لمنشأة.","requirements":["رخصة تجارية، أو حجز اسم تجاري ووصل الموافقة المبدئية، أو خطاب عدم ممانعة من المنطقة الحرة، بحسب الحالة.","اشتراطات ومستندات وكوادر إضافية حسب رمز النشاط في جدول SIRA؛ لا توجد قائمة موحدة لجميع الأنشطة."],"fees":"تعرض البطاقة 100 درهم للخدمة و10 معرفة و10 ابتكار، إضافة إلى جدول رسوم مختلف حسب النشاط؛ لا تعتبر 120 درهمًا إجمالي ترخيص كل نشاط. طابق رمز النشاط والإجمالي في المصدر الرسمي قبل الدفع.","duration":"يومان عمل وفق بطاقة الخدمة؛ ليست ضمانًا للقبول.","conditions":"لأنشطة الأمن في دبي فقط. لا تبدأ ممارسة النشاط قبل استيفاء الاشتراطات الأمنية أو الكوادر المطلوبة للنشاط. هذه خدمة إصدار جديد؛ التجديد والتعديل والإلغاء معاملات مختلفة.","officialUrl":"https://www.sira.gov.ae/ar/services/noc-security-license","executionUrlEn":"https://www.sira.gov.ae/en/services/noc-security-license","lastVerified":"2026-10-14","keywords":["سيرا","SIRA","موافقة سيرا","ترخيص نشاط أمني","Security activity licence","Security Industry Regulatory Agency"],"localizedDetails":{"en":{"documents":["Trade licence, or trade-name reservation and initial approval inquiry receipt, or a free-zone NOC, as applicable.","Additional requirements and security staff depend on the activity code in SIRA's official table."],"fees":"The card lists AED 100 service, AED 10 knowledge and AED 10 innovation fees, alongside separate activity-specific amounts. AED 120 is not a universal activity licence total; check the activity code and final official amount.","duration":"Two business days according to the service card; not an approval guarantee.","eligibility":"Dubai security activities only. Meet the activity-specific security or personnel conditions before operating. This is new issuance; renewal, amendment and cancellation are distinct transactions."}},"sourceUrl":"https://www.sira.gov.ae/en/services/noc-security-license"},{"id":"sira:security-system-certification","slug":"sira-security-system-certification-dubai","nameAr":"إصدار شهادة اعتماد نظام أمني للمنشأة في دبي","nameEn":"New Security System Certification","category":"government-approvals","type":"اعتماد نظام أمني لمنشأة","description":"اعتماد مطابقة النظام الأمني للمنشأة لاشتراطات SIRA في دبي. تختلف مستندات المنشآت التجارية عن المباني؛ لا تحل الشهادة محل ترخيص شركة أمنية.","requirements":["للمنشآت التجارية: حجز الاسم ووصل الموافقة الأولية أو الرخصة التجارية؛ وللمناطق الحرة خطاب طلب الموافقة المبدئية بحسب البطاقة.","للمباني: مخطط الأرض أو الرخصة التجارية.","شهادة اعتماد مخطط أمني مختومة من الاستشاري وشركة تركيب الأنظمة، وتقرير تدقيق أمني ناجح."],"fees":"100 درهم للخدمة و10 دراهم معرفة و10 دراهم ابتكار وفق البطاقة؛ لا يشمل ذلك أي خدمات أو أعمال أمنية أخرى غير مدرجة.","duration":"يومان عمل وفق بطاقة الخدمة؛ ليست ضمانًا للقبول.","conditions":"للمنشآت والمباني في دبي حسب الفئة. شهادة اعتماد المخطط الأمني إلزامية قبل طلب التدقيق، ولا يبدأ النشاط قبل الحصول على تقرير تدقيق ناجح. راجع الاشتراطات الخاصة بالنشاط أو المبنى.","officialUrl":"https://www.sira.gov.ae/ar/services/security-system-certification","executionUrlEn":"https://www.sira.gov.ae/en/services/security-system-certification","lastVerified":"2026-10-14","keywords":["سيرا","SIRA","موافقة كاميرات مراقبة","موافقة الأنظمة الأمنية","Security system certification Dubai","CCTV"],"localizedDetails":{"en":{"documents":["Business establishments: trade-name reservation and initial approval receipt, or trade licence; free zones use the initial approval request letter as listed.","Buildings: plot affection plan or trade licence.","Approved security plan stamped by the consultancy and installation company, and a successful security audit report."],"fees":"AED 100 service fee, AED 10 knowledge and AED 10 innovation according to the card. Other security work or services are not included.","duration":"Two business days according to the service card; not an approval guarantee.","eligibility":"Dubai establishments and buildings, according to the applicable category. An approved security plan is required before requesting the audit. Do not operate before a successful audit report; check the activity or building-specific requirements."}},"sourceUrl":"https://www.sira.gov.ae/en/services/security-system-certification"}]$facts$::jsonb) loop
  insert into public.hb_policy_sources(jurisdiction_id,authority_key,title,source_url,source_type,last_verified_at,active,metadata,country_pack_id,authority_id) values(j,'sira-dubai',item->>'nameAr',item->>'sourceUrl','official',reviewed,true,jsonb_build_object('service_slug',item->>'slug','review_result','approved_for_user_navigation','verification_scope','service_identity_and_scoped_recorded_facts','arabic_source',item->>'officialUrl'),cp,a) on conflict(authority_key,source_url) do nothing;
  select id into strict sid from public.hb_policy_sources where authority_key='sira-dubai' and source_url=item->>'sourceUrl' and active;
  select coalesce(jsonb_agg(jsonb_build_object('id','requirement-'||ordinality,'when','[]'::jsonb,'effect','review','reason',value#>>'{}','actions',jsonb_build_array('review_documents'),'sourceRefs',jsonb_build_array(item->>'sourceUrl'))),'[]'::jsonb) into rules from jsonb_array_elements(item->'requirements') with ordinality;
  rules:=rules||jsonb_build_array(jsonb_build_object('id','fees','when','[]'::jsonb,'effect','review','reason',item->>'fees','actions',jsonb_build_array('review_fees'),'sourceRefs',jsonb_build_array(item->>'sourceUrl')),jsonb_build_object('id','duration','when','[]'::jsonb,'effect','review','reason',item->>'duration','actions',jsonb_build_array('review_duration'),'sourceRefs',jsonb_build_array(item->>'sourceUrl')),jsonb_build_object('id','conditions','when','[]'::jsonb,'effect','review','reason',item->>'conditions','actions',jsonb_build_array('review_conditions'),'sourceRefs',jsonb_build_array(item->>'sourceUrl')));
  insert into public.hb_policy_versions(policy_key,jurisdiction_id,version,effective_from,status,rules,source_ids,reviewed_by,reviewed_at,country_pack_id) values('service:'||(item->>'slug'),j,1,reviewed,'active',rules,array[sid],'sira-official-card-review-2026-10-14',reviewed,cp) on conflict(policy_key,jurisdiction_id,version) do nothing;
  insert into public.hb_workflow_templates(workflow_key,jurisdiction_id,service_slug,version,status,definition,effective_from,country_pack_id) values('service:'||(item->>'slug'),j,item->>'slug',1,'active',jsonb_build_object('id','service:'||(item->>'slug'),'version',1,'name',item->>'nameAr','serviceSlug',item->>'slug','steps',jsonb_build_array(jsonb_build_object('key','intake','title','تحديد نوع الخدمة والمنشأة ورمز النشاط','taskType','intake','assigneeType','user'),jsonb_build_object('key','review','title','مراجعة المتطلبات المحددة في بطاقة SIRA الرسمية','taskType','review','assigneeType','user'),jsonb_build_object('key','external-execution','title','التقديم والسداد والمتابعة عبر بوابة SIRA الرسمية','taskType','external','assigneeType','user','requiresApproval',true,'risk',jsonb_build_object('externalSubmission',true),'metadata',jsonb_build_object('officialUrl',item->>'sourceUrl','executionMode','manual-official-route')))),reviewed,cp) on conflict(workflow_key,jurisdiction_id,version) do nothing;
  insert into public.hb_service_bindings(service_slug,jurisdiction_id,authority_key,policy_key,workflow_key,execution_mode,active,metadata,country_pack_id,authority_id) values(item->>'slug',j,'sira-dubai','service:'||(item->>'slug'),'service:'||(item->>'slug'),'guidance',true,jsonb_build_object('name',item->>'nameAr','name_en',item->>'nameEn','category','government-approvals','emirate','دبي','officialUrl',item->>'sourceUrl','executionUrl',item->>'sourceUrl','public_catalog',true,'governmentDetailsVerified',true,'keywords',item->'keywords'),cp,a) on conflict(service_slug,jurisdiction_id) do nothing;
 end loop;
end $review$;
commit;
